            for(int i=0;i<items.Count;i++){if(stopBatch)break;var entry=items[i];if(entry.State is "완료 · 검증 일치" or "제외")continue;if(entry.TargetId!=""&&entry.TargetId!=target){failed++;lastFailure="중단된 작업은 원래 기기를 선택하세요. 다른 기기로 보내려면 취소·정리 후 다시 추가하세요.";Update(i,"실패 · 원래 기기를 선택하세요");ShowError("전송",new V2Error(409,lastFailure));continue;}entry.TargetId=target;activeIndex=i;current=new();Update(i,"준비 중");bar.Value=0;
                try{if(!SaveQueue())throw new V2Error(507,"전송 준비 정보를 저장하지 못했습니다. PC 저장 공간을 확인하세요.");int index=i;var token=current.Token;var progress=new Progress<TransferProgress>(p=>{if(current==null||token.IsCancellationRequested||activeIndex!=index||closing)return;bar.Value=p.Total>0?(int)Math.Clamp(p.Sent*1000.0/p.Total,0,1000):0;queue.Items[index].SubItems[2].Text=$"{p.Stage} {bar.Value/10}%";status.Text=$"{entry.Relative} · {p.Stage}";});
                    var receipt=await client.Send(endpoint,target,entry.Source,entry.Relative,entry.Id,entry.BatchId,entry.Directory,progress,current.Token);Update(i,"완료 · 검증 일치");bar.Value=1000;ok++;AddHistory("보냄 · 완료",entry.Relative,receipt.Size);
                }catch(OperationCanceledException){Update(i,"중단 · 이어보내기");AddHistory("보냄 · 중단",entry.Relative,0);}
                catch(Exception e){Update(i,"실패 · 이어보내기");failed++;lastFailure=ErrorText(e);ShowError(entry.Relative,e);}
                finally{current.Dispose();current=null;activeIndex=-1;SaveQueue();}
            }status.Text=$"처리 종료 · 완료 {ok} / 실패 {failed}."+(lastFailure!=""?"\n마지막 오류: "+lastFailure:" 중단 항목은 같은 기기를 선택하고 다시 보내면 이어집니다.");
        }catch(Exception e){ShowError("전송 시작",e);}finally{batch=null;SetBusy(false);SaveQueue();}
    }
    void SetBusy(bool busy){choose.Enabled=send.Enabled=check.Enabled=ip.Enabled=port.Enabled=peers.Enabled=scan.Enabled=pair.Enabled=registered.Enabled=!busy;}
    async Task Scan(){if(scanControl!=null||closing||selecting)return;scanControl=CancellationTokenSource.CreateLinkedTokenSource(lifetime.Token);scan.Enabled=false;status.Text="같은 네트워크의 기기를 찾는 중…";try{var found=await DiscoveryScanner.ScanAsync(settings.DeviceId,scanControl.Token);if(closing)return;discovered.Clear();foreach(var p in found){discovered[p.Id]=p;directory.Seen(p.Id,p.Endpoint);}if(discovered.TryGetValue(selectedId,out var remembered))ApplyEndpoint(remembered.Endpoint);RefreshRegistered();status.Text=found.Count==0?"검색된 기기가 없습니다. 등록된 기기를 누르면 기억한 주소에서도 연결을 확인합니다.":$"{found.Count}개 기기를 찾았습니다. 등록된 기기 또는 이름을 선택하세요.";}catch(OperationCanceledException){}catch(Exception e){if(!closing)ShowError("기기 찾기",e);}finally{scanControl.Dispose();scanControl=null;if(!closing)scan.Enabled=batch==null&&!selecting;}}
    void ApplyEndpoint(DeviceEndpoint endpoint){applyingEndpoint=true;try{ip.Text=endpoint.Address.ToString();port.Text=endpoint.Port.ToString();}finally{applyingEndpoint=false;}SaveEndpoint();}
    void ValidateTarget(RemoteInfo remote){if(selectedId!=""&&remote.Id!=selectedId)throw new V2Error(403,"선택한 기기와 다른 기기가 응답했습니다. 다시 검색해 주세요.");}
    void ShowTarget(string? model=null,string state="선택 시 연결 확인") {var id=selectedId;var name=book.Find(id)?.Name??model??discovered.GetValueOrDefault(id)?.Name;targetLabel.Text=name==null?"받는 기기: 수동 IP · 연결 확인 필요":$"받는 기기: {directory.Display(id,name)} · {state}";}
    async Task SelectTarget(string id,string model){if(closing||selecting||batch!=null||current!=null)return;selecting=true;scanControl?.Cancel();selectedId=id;settings.LastDeviceId=id;settings.Save();ShowTarget(model,"연결 확인 중…");mainTabs.SelectedIndex=0;SetBusy(true);try{using var ct=CancellationTokenSource.CreateLinkedTokenSource(lifetime.Token);ct.CancelAfter(TimeSpan.FromSeconds(12));var found=await DiscoveryScanner.ScanAsync(settings.DeviceId,ct.Token);foreach(var p in found){discovered[p.Id]=p;directory.Seen(p.Id,p.Endpoint);}var endpoint=found.FirstOrDefault(p=>p.Id==id)?.Endpoint??directory.Hint(id)??throw new V2Error(404,"상대 기기를 찾지 못했습니다. 같은 Wi-Fi에서 상대 앱을 켜고 다시 선택하세요.");ApplyEndpoint(endpoint);var remote=await client.Inspect(endpoint,ct.Token);ValidateTarget(remote);ShowTarget(model,remote.ReceiveReady?"연결 가능":"수신 폴더 설정 필요");status.Text=remote.ReceiveReady?(book.Find(id)==null?"연결 가능 · 먼저 연결 승인을 요청하세요.":"연결 가능 · 파일을 추가한 뒤 보내세요."):remote.ReceiveMessage;}catch(Exception e){if(!closing){ShowTarget(model,"연결 확인 실패");ShowError("기기 선택",e);}}finally{selecting=false;if(!closing){SetBusy(false);RefreshRegistered();}}}
    static string ErrorText(Exception e)=>(e is V2Error v?$"HTTP {v.Code} · ":"")+e.Message;
    void ShowError(string action,Exception e){var text=action+" · "+ErrorText(e);settings.LastError=text;status.Text=text;AddHistory("오류",text,0);}
    void EditAlias(string id,string model){if(selecting||batch!=null||current!=null)return;using var dialog=new Form{Text="기기 별명 설정",ClientSize=new Size(470,190),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,Font=Font};var input=new TextBox{Left=20,Top=65,Width=420,Text=directory.Get(id).Alias};dialog.Controls.Add(new Label{Left=20,Top=18,Width=420,Height=40,Text=model+" (별명) · 비우면 모델명만 표시"});dialog.Controls.Add(input);var save=new CuteButton{Left=265,Top=120,Width=80,Text="저장"};var cancel=new CuteButton{Left=355,Top=120,Width=80,Text="취소",DialogResult=DialogResult.Cancel};dialog.Controls.AddRange([save,cancel]);dialog.AcceptButton=save;dialog.CancelButton=cancel;save.Click+=(_,_)=>{try{directory.SetAlias(id,input.Text);dialog.DialogResult=DialogResult.OK;}catch(Exception e){MessageBox.Show(dialog,e.Message);}};if(dialog.ShowDialog(this)==DialogResult.OK){RefreshRegistered();ShowTarget();}}
    void StartReceiver(){if(closing)return;try{var cache=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DropShip","v05","incoming");service=new V2Service(book,new TransferRepository(cache,new FilePublishStore(settings.ReceiveFolder)));service.Progress+=p=>UI(()=>{receiveState.Text=$"받는 중 · {p.Name}\n{p.Bytes/1048576.0:N1} / {p.Total/1048576.0:N1} MB";receiveBar.Value=p.Total>0?(int)Math.Clamp(p.Bytes*1000.0/p.Total,0,1000):0;});service.Completed+=r=>UI(()=>{receiveState.Text="수신 완료 · "+r.Name+" · SHA-256 일치";receiveBar.Value=1000;AddHistory("받음 · 완료",r.Name,r.Size);});service.Failed+=message=>UI(()=>{settings.LastError="받음 · "+message;receiveState.Text=settings.LastError;receiveBar.Value=0;AddHistory("받음 · 실패",message,0);});var server=new ReceiverV2(service);try{server.Start();}catch{_ =server.DisposeAsync();throw;}receiver=server;receiveState.Text="● 승인된 기기 수신 준비 완료";try{responder=new(settings.DeviceId,()=>settings.DeviceName,"windows");}catch{receiveState.Text+="\n자동 검색 불가 · 수동 IP를 사용하세요.";}}catch(Exception e){receiveState.Text="수신 시작 실패 · "+e.Message;}}
    async Task StopReceiver(){responder?.Dispose();responder=null;var old=receiver;receiver=null;if(old!=null)await old.DisposeAsync();}
    void UpdateAddress(){try{var addresses=NetworkInterface.GetAllNetworkInterfaces().Where(n=>n.OperationalStatus==OperationalStatus.Up).SelectMany(n=>n.GetIPProperties().UnicastAddresses).Where(a=>a.Address.AddressFamily==AddressFamily.InterNetwork&&!System.Net.IPAddress.IsLoopback(a.Address)).Select(a=>a.Address.ToString());address.Text="내 IP · "+string.Join(" / ",addresses)+"\nPort · 8765";}catch{address.Text="IP를 확인하지 못했습니다.";}}
}
